export interface Peer {
  send(message: ServerMessage): void;
  close(code: number, reason: string): void;
}

/** Closes every viewer connection of `userId` (member removed). */
disconnectUser(userId: string): void {
  for (const [peer, viewer] of [...this.viewers]) {
    if (viewer.userId !== userId) continue;
    this.viewerDisconnected(peer);
    peer.close(4003, "no_household");
  }
}

/** Closes every connection of a revoked camera. */
disconnectDevice(deviceId: string): void {
  const state = this.cameras.get(deviceId);
  for (const peer of [...(state?.peers ?? [])]) {
    state!.peers.delete(peer);
    peer.close(4003, "device_revoked");
  }
}

